  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// -----------------------------------------------------------------------------\n// ENUMS\n// -----------------------------------------------------------------------------\n\nenum UserRole {\n  DOCTOR\n  PHARMACY\n  PATIENT\n  ADMIN\n}\n\nenum PrescriptionStatus {\n  PENDING\n  FILLED\n  CANNOT_FILL\n}\n\n// -----------------------------------------------------------------------------\n// CORE USER & ROLE PROFILES\n// -----------------------------------------------------------------------------\n\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  role      UserRole\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // 1-to-1 Profile Relations\n  doctorProfile   DoctorProfile?\n  pharmacyProfile PharmacyProfile?\n  patientProfile  PatientProfile?\n\n  @@index([role])\n}\n\nmodel DoctorProfile {\n  id             String   @id @default(cuid())\n  userId         String   @unique\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  specialization String\n  licenseNumber  String   @unique\n  phone          String\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  // Relations\n  doctorPatients DoctorPatient[]\n  prescriptions  Prescription[]\n\n  @@index([specialization])\n}\n\nmodel PharmacyProfile {\n  id            String   @id @default(cuid())\n  userId        String   @unique\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  pharmacyName  String\n  pharmacyType  String\n  licenseNumber String   @unique\n  phone         String\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Relations\n  fills Fill[]\n\n  @@index([pharmacyName])\n}\n\nmodel PatientProfile {\n  id          String   @id @default(cuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name        String\n  age         Int\n  gender      String\n  contactInfo String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  doctorPatients DoctorPatient[]\n  prescriptions  Prescription[]\n\n  @@index([name])\n}\n\n// -----------------------------------------------------------------------------\n// DOCTOR-PATIENT ROSTER (JOIN ENTITY)\n// -----------------------------------------------------------------------------\n\nmodel DoctorPatient {\n  id        String         @id @default(cuid())\n  doctorId  String\n  doctor    DoctorProfile  @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  patientId String\n  patient   PatientProfile @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  @@unique([doctorId, patientId])\n  @@index([doctorId])\n  @@index([patientId])\n}\n\n// -----------------------------------------------------------------------------\n// MEDICINE CATALOG\n// -----------------------------------------------------------------------------\n\nmodel Medicine {\n  id          String   @id @default(cuid())\n  name        String\n  genericName String\n  stockStatus Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  prescriptionMedicines PrescriptionMedicine[]\n\n  @@index([name])\n  @@index([genericName])\n}\n\n// -----------------------------------------------------------------------------\n// PRESCRIPTION & FULFILLMENT TRACKING\n// -----------------------------------------------------------------------------\n\nmodel Prescription {\n  id          String             @id @default(cuid())\n  doctorId    String\n  doctor      DoctorProfile      @relation(fields: [doctorId], references: [id], onDelete: Restrict)\n  patientId   String\n  patient     PatientProfile     @relation(fields: [patientId], references: [id], onDelete: Restrict)\n  diagnosis   String\n  documentRef String?\n  status      PrescriptionStatus @default(PENDING)\n  filledAt    DateTime?\n  createdAt   DateTime           @default(now())\n  updatedAt   DateTime           @updatedAt\n\n  // Relations\n  prescriptionMedicines PrescriptionMedicine[]\n  fill                  Fill?\n\n  @@index([doctorId])\n  @@index([patientId])\n  @@index([status])\n  @@index([createdAt])\n}\n\nmodel PrescriptionMedicine {\n  id             String       @id @default(cuid())\n  prescriptionId String\n  prescription   Prescription @relation(fields: [prescriptionId], references: [id], onDelete: Cascade)\n  medicineId     String\n  medicine       Medicine     @relation(fields: [medicineId], references: [id], onDelete: Restrict)\n  dosage         String\n  frequency      String\n  duration       String\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  @@unique([prescriptionId, medicineId])\n  @@index([prescriptionId])\n  @@index([medicineId])\n}\n\nmodel Fill {\n  id             String          @id @default(cuid())\n  prescriptionId String          @unique // 1-to-1 unique constraint: a prescription can have at most one successful fill\n  prescription   Prescription    @relation(fields: [prescriptionId], references: [id], onDelete: Cascade)\n  pharmacyId     String\n  pharmacy       PharmacyProfile @relation(fields: [pharmacyId], references: [id], onDelete: Restrict)\n  notes          String?\n  filledAt       DateTime        @default(now())\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  @@index([pharmacyId])\n  @@index([filledAt])\n}\n",
